# Example scales and rule from a team's plan (not from ISO 14971)
P_LEVELS = [(1e-2, 5), (1e-3, 4), (1e-4, 3), (1e-5, 2), (0.0, 1)]

def p_level(p):
    for limit, level in P_LEVELS:
        if p >= limit:
            return level

def acceptable(severity, level):
    if severity >= 4:
        return level <= 2
    return severity * level <= 8

p1 = 1 / 1000   # wrong dose shown, per use (test data)
p2 = 1 / 10     # user acts on it (team judgement)
level = p_level(p1 * p2)
print("P level", level, "acceptable:", acceptable(4, level))
# P level 3 acceptable: False

# Find controls with no passing verification in an exported risk table
rows = [
    {"risk": "R-07", "control": "SR-41", "test": "VT-120", "result": "pass"},
    {"risk": "R-07", "control": "SR-42", "test": "VT-121", "result": "fail"},
    {"risk": "R-07", "control": "SR-43", "test": None, "result": None},
]
for r in rows:
    if r["test"] is None:
        print(r["control"], "has no verification test")
    elif r["result"] != "pass":
        print(r["control"], "test", r["test"], "is", r["result"])
# SR-42 test VT-121 is fail
# SR-43 has no verification test
